"""P8-B3 — G4, the false-failure rate, and the independence check that F2 and F5 exist for.

**F5 — `clean_corpus_independent_of_predicate` is COMPUTED, NEVER DECLARED.** Before this pass it
was a field in a YAML file that **no build computed, no test asserted, no negative control broke
and no gate read**. It is now the return value of `independent()`, there is no setter and no
constructor argument, and the loader REFUSES a record whose stored value disagrees with a
recomputation.

**F2 — the corpus was generated by the code under test.** A `sum_identity` predicate checked
against a filing whose totals `src/cdfc/calc/` computed is re-checking our answer against our
answer. Its expected FFR is zero **regardless of the predicate's quality**, which is this plan's
own definition of an uninformative rate — and at `n = 189` it bought a `BLOCKING` tier in an
afternoon.

**Both failures raise the SAME exception from the SAME function**, so there is no second code path
to forget:

    check() raises UninformativeCorpusError when
      * corpus.provenance is SELF-AUTHORED, or
      * independent(corpus, cand) is False.

**NOT "returns 0". NOT "returns a rate with a caveat". RAISES** — because a caveat is a string
somebody drops when they reformat a table, and an exception is not. The outcome records WHICH
conjunct failed, the intersecting cells and the intersecting modules, because *a rejection whose
reason is not reconstructible is not a rejection*.
"""

from __future__ import annotations

from collections.abc import Mapping, Sequence
from dataclasses import dataclass
from decimal import Decimal
from typing import Any, Final

from cdfc.importgraph import import_closure
from cdfc.qualify.corpus.provenance import (
    NON_SYNTHETIC,
    CorpusProvenance,
    UninformativeCorpusError,
)
from cdfc.qualify.corpus.template_computed import CleanFiling, DerivedBy
from cdfc.qualify.result import GateId, GateOutcome
from cdfc.qualify.set_ffr import FireMatrix, ffr, marginal_ffr
from cdfc.qualify.wilson import wilson

# The evaluator a predicate is run through. Its import closure is the second half of conjunct (1)'s
# escape hatch: a FOREIGN_ENGINE corpus is independent when the derivation shares no module with
# the thing that re-checks it.
EVALUATOR_MODULE: Final[str] = "cdfc.evaluate.runner"

MAX_NAMED_CELLS: Final[int] = 12  # a rejection names its evidence; it does not paste a table


class Reason:
    SELF_AUTHORED: Final[str] = "g4.self_authored_corpus"
    NOT_INDEPENDENT: Final[str] = "g4.corpus_not_independent"
    ABOVE_ADVISORY: Final[str] = "g4.ffr_above_advisory"


@dataclass(frozen=True, slots=True)
class CleanCorpus:
    """A corpus of clean filings, all of one provenance and one derivation."""

    corpus_id: str
    filings: tuple[CleanFiling, ...]

    def __post_init__(self) -> None:
        if not self.filings:
            raise ValueError(f"{self.corpus_id}: a corpus of no filings is not a corpus")
        if len({f.provenance for f in self.filings}) != 1:
            raise ValueError(
                f"{self.corpus_id}: filings of mixed provenance in one corpus. What a rate is "
                "drawn from is part of the rate."
            )
        if len({f.derived_by for f in self.filings}) != 1:
            raise ValueError(f"{self.corpus_id}: filings of mixed derivation in one corpus")

    @property
    def provenance(self) -> CorpusProvenance:
        return self.filings[0].provenance

    @property
    def derived_by(self) -> DerivedBy:
        return self.filings[0].derived_by

    @property
    def engine_digest(self) -> str | None:
        return self.filings[0].derived_engine_digest

    @property
    def computed_cells(self) -> frozenset[str]:
        out: set[str] = set()
        for f in self.filings:
            out |= f.computed_cells
        return frozenset(out)

    @property
    def generator_import_closure(self) -> frozenset[str]:
        return self.filings[0].generator_import_closure

    @property
    def n(self) -> int:
        return len(self.filings)

    @property
    def n_non_synthetic(self) -> int:
        """Filings a PERSON or THE WORLD produced. Gates `BLOCKING`, and nothing else does."""
        return sum(1 for f in self.filings if f.provenance in NON_SYNTHETIC)

    @property
    def label(self) -> str:
        return self.filings[0].label


@dataclass(frozen=True, slots=True)
class Independence:
    """The RESULT of a computation. There is no way to construct one that says `True` falsely
    without the cells and modules to back it."""

    independent: bool
    conjunct_failed: str | None
    intersecting_cells: tuple[str, ...]
    intersecting_modules: tuple[str, ...]

    def as_mapping(self) -> Mapping[str, object]:
        return {
            "clean_corpus_independent_of_predicate": self.independent,
            "conjunct_failed": self.conjunct_failed,
            "intersecting_cells": list(self.intersecting_cells),
            "intersecting_modules": list(self.intersecting_modules),
        }


def evaluation_import_closure(cand: Any) -> frozenset[str]:
    """The modules a predicate's evaluation reaches. By AST, without importing anything."""
    return frozenset(set(import_closure(EVALUATOR_MODULE)) | {EVALUATOR_MODULE})


def read_cells(cand: Any, schema: Any) -> frozenset[str]:
    """The cells this predicate READS, exactly — from P4's both-ways AST check, not an estimate."""
    from cdfc.predicates.ast_walker import bound_cells

    return frozenset(bound_cells(cand, schema))


def independent(corpus: CleanCorpus, cand: Any, schema: Any) -> Independence:
    """**COMPUTED, NEVER DECLARED (F5).** Both conjuncts, in this order.

    (1) `read_cells(cand) & corpus.computed_cells == ∅` — the predicate does not re-check a cell
        the corpus generator derived; **OR** `derived_by is FOREIGN_ENGINE` and
        `generator_import_closure & evaluation_import_closure(cand) == ∅` — the derivation shares
        no module with the thing that re-checks it.
    (2) `corpus.provenance is not SELF_AUTHORED`.

    **THERE IS NO SETTER.** `clean_corpus_independent_of_predicate` is the result of this call.
    """
    if corpus.provenance is CorpusProvenance.SELF_AUTHORED:
        return Independence(False, "provenance", (), ())

    overlap = sorted(read_cells(cand, schema) & corpus.computed_cells)
    if not overlap:
        return Independence(True, None, (), ())

    if corpus.derived_by is DerivedBy.FOREIGN_ENGINE:
        shared = sorted(corpus.generator_import_closure & evaluation_import_closure(cand))
        if not shared:
            # The predicate re-checks a derived cell, but a program sharing no module with ours
            # derived it. That is an independent oracle, and it is the whole point of the mode.
            return Independence(True, None, tuple(overlap[:MAX_NAMED_CELLS]), ())
        return Independence(False, "closure", tuple(overlap[:MAX_NAMED_CELLS]),
                            tuple(shared[:MAX_NAMED_CELLS]))

    return Independence(False, "computed_cells", tuple(overlap[:MAX_NAMED_CELLS]), ())


def check(
    cand: Any,
    corpus: CleanCorpus,
    fires: FireMatrix,
    admitted: Sequence[str],
    schema: Any,
    *,
    person_a_kind: str = "n/a",
    advisory_max: Decimal = Decimal("0.10"),
) -> GateOutcome:
    """One predicate's FFR against one corpus. Raises rather than carrying a number forward."""
    if corpus.provenance is CorpusProvenance.SELF_AUTHORED:
        raise UninformativeCorpusError(
            f"{cand.id}: corpus {corpus.corpus_id!r} is SELF-AUTHORED. An FFR measured on a corpus "
            "its authors also wrote has expected value zero regardless of predicate quality. "
            "Printing '0.0% false failures' would be worse than printing nothing, because it has "
            "the shape of evidence."
        )

    ind = independent(corpus, cand, schema)
    if not ind.independent:
        raise UninformativeCorpusError(
            f"{cand.id}: corpus {corpus.corpus_id!r} is not independent of this predicate "
            f"(conjunct {ind.conjunct_failed!r}). It reads {len(ind.intersecting_cells)}+ cell(s) "
            f"the generator derived, e.g. {list(ind.intersecting_cells[:3])}"
            + (f"; shared modules {list(ind.intersecting_modules[:3])}" if ind.intersecting_modules else "")
            + ". A predicate re-checking our answer against our answer has measured nothing."
        )

    fired = len(fires.of(cand.id))
    point, lo, hi = wilson(fired, corpus.n)
    marginal, conditioned_on = marginal_ffr(admitted, cand.id, fires)

    measured: dict[str, object] = {
        "fired": fired,
        "n": corpus.n,  # FILINGS. never cells.
        "rate": str(ffr(cand.id, fires)),
        "wilson": [str(lo), str(hi)],
        "corpus_id": corpus.corpus_id,
        "corpus_provenance": corpus.provenance.value,
        "corpus_derived_by": corpus.derived_by.value,
        "corpus_derived_engine_digest": corpus.engine_digest,
        "n_non_synthetic": corpus.n_non_synthetic,
        "person_a_kind": person_a_kind,
        "corpus_label": corpus.label,
        "marginal_ffr": f"{marginal.numerator}/{marginal.denominator}",
        "conditioned_on": list(conditioned_on),
        "heldout": None,
        **ind.as_mapping(),
    }

    if hi > advisory_max:
        return GateOutcome(gate=GateId.G4, passed=False, measured=measured,
                           reason=Reason.ABOVE_ADVISORY)
    return GateOutcome(gate=GateId.G4, passed=True, measured=measured)


REQUIRED_G4_FIELDS: Final[tuple[str, ...]] = (
    "fired", "n", "rate", "wilson", "corpus_id", "corpus_provenance", "corpus_derived_by",
    "n_non_synthetic", "marginal_ffr", "conditioned_on",
    "clean_corpus_independent_of_predicate",
)


class IncompleteG4Record(ValueError):
    """A `qualification.g4` missing a required field. **The predicate does not load.**"""


def load_g4(record: Mapping[str, object], corpus: CleanCorpus, cand: Any, schema: Any) -> Mapping[str, object]:
    """Read a stored `g4` block back, RECOMPUTING independence and refusing a disagreement (F5)."""
    missing = [f for f in REQUIRED_G4_FIELDS if f not in record]
    if missing:
        raise IncompleteG4Record(
            f"{cand.id}: qualification.g4 is missing {missing}. Absent any field, the predicate "
            "does not load — an FFR whose provenance, denominator or interval is missing is a "
            "number with the shape of evidence."
        )
    recomputed = independent(corpus, cand, schema).independent
    stored = record["clean_corpus_independent_of_predicate"]
    if stored != recomputed:
        raise IncompleteG4Record(
            f"{cand.id}: the record says clean_corpus_independent_of_predicate={stored!r} and a "
            f"recomputation says {recomputed!r}. **There is no setter for this field.** It is the "
            "field that would have caught F2 and that, before this build, no build computed, no "
            "test asserted, no negative control broke and no gate read."
        )
    return record
